export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const g = 9.81;
  const m0 = 0.725;
  const drag0 = 0.42 / m0;
  const kT0 = 15.5 / m0;

  let initialized = false;
  let vf = { x: 0, y: 0, z: 0 };
  let prevVf = { x: 0, y: 0, z: 0 };
  let dSlow = { x: 0, y: 0, z: 0 };
  let dFast = { x: 0, y: 0, z: 0 };
  let uThrust = 0.46;
  let lastThrust = 0.46;

  let intX = 0, intY = 0, intZ = 0, intYaw = 0;
  let ref = { x: 0, y: 0, z: 0 };
  let refVel = { x: 0, y: 0, z: 0 };

  let activeGateIdx = 0;
  let lockedGate = null;
  let phase = 'align'; // 'align', 'cross', 'exit', 'pad'
  let settle = 0;
  let padY = 0.65;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        vf = { x: v.x, y: v.y, z: v.z };
        prevVf = { x: v.x, y: v.y, z: v.z };
        ref = { x: p.x, y: Math.max(p.y, 0.25), z: p.z };
        if (obs.nextGate) lockedGate = { ...obs.nextGate.centre };
      }

      // 1. Filter velocity
      const alphaV = 0.42;
      for (const a of ['x', 'y', 'z']) {
        prevVf[a] = vf[a];
        vf[a] += alphaV * (v[a] - vf[a]);
      }

      // 2. Fast/slow acceleration disturbance observer
      uThrust += (lastThrust - uThrust) * (1 - Math.exp(-dt / 0.038));
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const bodyX = sp * cr, bodyZ = -sr;
      const dir = {
        x: cy * bodyX + sy * bodyZ,
        y: cp * cr,
        z: -sy * bodyX + cy * bodyZ,
      };

      const aMeasY = (vf.y - prevVf.y) / dt;
      const aNomY = kT0 * uThrust * dir.y - drag0 * vf.y - g;
      const dRawY = clamp(aMeasY - aNomY, -8, 8);
